import React, { useState } from 'react';
import { Modal, Form, Input, Select, Space, Button, message } from 'antd';
import { apiRequest } from '../api';

interface Props {
  open: boolean;
  onClose: () => void;
  onApproved?: (requestId: string) => void;
}

const TwoKeysModal: React.FC<Props> = ({ open, onClose, onApproved }) => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [requestId, setRequestId] = useState<string>('');

  const createRequest = async () => {
    try {
      const v = await form.validateFields();
      setLoading(true);
      const resp = await apiRequest('/api/admin/two-keys/requests', 'POST', v);
      const rid = String(resp?.id || resp?.request_id || '');
      setRequestId(rid);
      message.success(rid ? `Создана заявка: ${rid}` : 'Заявка создана');
    } catch (e: any) {
      if (e?.status === 403) { message.error('403: нет прав'); return; }
      message.error(e?.message || 'Ошибка создания заявки');
    } finally {
      setLoading(false);
    }
  };

  const approve = async () => {
    try {
      const rid = requestId.trim();
      if (!rid) { message.warning('Нет request_id'); return; }
      setLoading(true);
      await apiRequest('/api/admin/two-keys/approve', 'POST', { request_id: rid });
      message.success('Подтверждено');
      onApproved?.(rid);
      onClose();
    } catch (e: any) {
      if (e?.status === 403) { message.error('403: нет прав/аппрува'); return; }
      message.error(e?.message || 'Ошибка подтверждения');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal open={open} onCancel={onClose} title="Two-Keys" footer={null}>
      <Form form={form} layout="vertical">
        <Form.Item name="operation" label="Операция" rules={[{ required: true }]}>
          <Select options={[
            { value: 'incident.close', label: 'incident.close' },
            { value: 'incident.rca_edit', label: 'incident.rca_edit' },
          ]} />
        </Form.Item>
        <Form.Item name="scope" label="Скоуп" rules={[{ required: true }]}>
          <Input placeholder="incident:{id}" />
        </Form.Item>
        <Form.Item name="reason" label="Причина" rules={[{ required: true }]}>
          <Input.TextArea rows={3} />
        </Form.Item>
        <Space style={{ display: 'flex', justifyContent: 'space-between' }}>
          <Button onClick={createRequest} loading={loading} type="primary">Создать заявку</Button>
          <Space>
            <Input placeholder="request_id" value={requestId} onChange={(e) => setRequestId(e.target.value)} />
            <Button onClick={approve} loading={loading} type="primary">Подтвердить</Button>
          </Space>
        </Space>
      </Form>
    </Modal>
  );
};

export default TwoKeysModal;


