import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Card, Space, Tag, Typography, Descriptions, Timeline, Button, Modal, Form, Input, Select, message } from 'antd';
import dayjs from 'dayjs';
import { apiRequest, API_BASE } from '../api';
import TwoKeysModal from '../components/TwoKeysModal';

type Incident = {
  id: string | number;
  title?: string;
  status?: string;
  severity?: number | string;
  source?: string;
  trace_id?: string;
  detected_at?: string;
  updated_at?: string;
  resolved_at?: string;
  closed_at?: string;
  sla?: any;
};

type IncidentEvent = {
  id: string | number;
  created_at?: string;
  type?: string;
  actor?: string;
  payload?: any;
  message?: string;
};

type IncidentLink = {
  id: string | number;
  to_kind: string;
  to_id: string | number;
  relation?: string;
};

const severityTag = (sev?: number | string) => {
  const n = typeof sev === 'string' ? parseInt(sev, 10) : (sev ?? 0);
  const map: Record<number, { color: string; text: string }> = {
    1: { color: 'red', text: 'SEV1' },
    2: { color: 'volcano', text: 'SEV2' },
    3: { color: 'orange', text: 'SEV3' },
    4: { color: 'gold', text: 'SEV4' },
    5: { color: 'green', text: 'SEV5' },
  };
  const cfg = map[n] || { color: 'default', text: String(sev ?? '-') };
  return <Tag color={cfg.color}>{cfg.text}</Tag>;
};

const statusTag = (status?: string) => {
  const s = String(status || '').toLowerCase();
  const color = s === 'open' ? 'red' : s === 'in_progress' ? 'gold' : s === 'resolved' ? 'green' : s === 'closed' ? 'default' : 'blue';
  return <Tag color={color}>{status || '-'}</Tag>;
};

const IncidentDetails: React.FC = () => {
  const { id } = useParams();
  const nav = useNavigate();

  const [loading, setLoading] = useState<boolean>(false);
  const [item, setItem] = useState<Incident | null>(null);
  const [events, setEvents] = useState<IncidentEvent[]>([]);
  const [links, setLinks] = useState<IncidentLink[]>([]);

  const [assignOpen, setAssignOpen] = useState<boolean>(false);
  const [assignForm] = Form.useForm();

  const [eventOpen, setEventOpen] = useState<boolean>(false);
  const [eventForm] = Form.useForm();

  const [linkOpen, setLinkOpen] = useState<boolean>(false);
  const [linkForm] = Form.useForm();

  const [tkOpen, setTkOpen] = useState<boolean>(false);
  const [tkAction, setTkAction] = useState<'close'|'close_with_postmortem'|'rca_edit_event'|'postmortem_finalize'>('close');
  const [pendingEvent, setPendingEvent] = useState<any | null>(null);
  const [pmStatus, setPmStatus] = useState<any | null>(null);
  const [pmCompareOpen, setPmCompareOpen] = useState<boolean>(false);
  const [pmDraftMD, setPmDraftMD] = useState<string>('');
  const [pmFinalMD, setPmFinalMD] = useState<string>('');

  const load = useCallback(async () => {
    try {
      setLoading(true);
      const resp = await apiRequest(`/api/admin/incidents/${id}`, 'GET');
      setItem(resp?.incident || resp || null);
      setEvents(resp?.incident_events || resp?.events || []);
      setLinks(resp?.incident_links || resp?.links || []);
    } catch (e: any) {
      message.error(e?.message || 'Ошибка загрузки инцидента');
    } finally {
      setLoading(false);
    }
  }, [id]);

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    (async () => {
      try {
        const s = await apiRequest(`/api/admin/incidents/${id}/postmortem/status`, 'GET');
        setPmStatus(s || null);
      } catch {}
    })();
  }, [id]);

  const addEvent = async () => {
    try {
      const v = await eventForm.validateFields();
      const sev = typeof item?.severity === 'string' ? parseInt(item?.severity, 10) : (item?.severity as any);
      if (String(v?.type) === 'rca_edit' && (sev === 1 || sev === 2)) {
        // Для SEV1/2 правка RCA через Two-Keys
        setPendingEvent(v);
        setTkAction('rca_edit_event');
        setTkOpen(true);
        return;
      }
      await apiRequest(`/api/admin/incidents/${id}/events`, 'POST', v);
      setEventOpen(false);
      eventForm.resetFields();
      await load();
      message.success('Событие добавлено');
    } catch (e: any) {
      if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
      message.error(e?.message || 'Ошибка добавления события');
    }
  };

  const addLink = async () => {
    try {
      const v = await linkForm.validateFields();
      await apiRequest(`/api/admin/incidents/${id}/links`, 'POST', v);
      setLinkOpen(false);
      linkForm.resetFields();
      await load();
      message.success('Связь добавлена');
    } catch (e: any) {
      if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
      message.error(e?.message || 'Ошибка добавления связи');
    }
  };

  const routeArchitect = async () => {
    try {
      await apiRequest(`/api/admin/incidents/${id}/route/architect`, 'POST', {});
      message.success('Эскалация отправлена архитектору');
      await load();
    } catch (e: any) {
      if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
      message.error(e?.message || 'Ошибка эскалации');
    }
  };

  const closeIncident = async () => {
    try {
      await apiRequest(`/api/admin/incidents/${id}/close`, 'POST', {});
      message.success('Инцидент закрыт');
      await load();
    } catch (e: any) {
      if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
      message.error(e?.message || 'Ошибка закрытия');
    }
  };

  const closeWithPostmortem = async () => {
    try {
      await apiRequest(`/api/admin/incidents/${id}/close_with_postmortem`, 'POST', {});
      message.success('Инцидент закрыт с Postmortem');
      await load();
    } catch (e: any) {
      if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
      message.error(e?.message || 'Ошибка закрытия с Postmortem');
    }
  };

  const header = useMemo(() => (
    <Space align="center">
      <Typography.Title level={4} style={{ margin: 0 }}>Инцидент #{item?.id}</Typography.Title>
      {statusTag(item?.status)}
      {severityTag(item?.severity)}
      {item?.trace_id ? <Tag color="cyan">{item?.trace_id}</Tag> : null}
    </Space>
  ), [item]);

  return (
    <Space direction="vertical" size={16} style={{ width: '100%' }}>
      <Space align="center" style={{ display: 'flex', justifyContent: 'space-between' }}>
        <div>{header}</div>
        <Space>
          <Button onClick={() => nav('/incidents')}>К списку</Button>
          <Button onClick={routeArchitect}>Escalate to Architect</Button>
          <Button
            onClick={async () => {
              const sev = typeof item?.severity === 'string' ? parseInt(item?.severity, 10) : (item?.severity as any);
              if (sev === 1 || sev === 2) { setTkAction('postmortem_finalize'); setTkOpen(true); return; }
              try {
                await apiRequest(`/api/admin/incidents/${id}/postmortem/finalize`, 'POST', {});
                message.success('Postmortem финализирован');
                const s = await apiRequest(`/api/admin/incidents/${id}/postmortem/status`, 'GET');
                setPmStatus(s || null);
              } catch (e: any) {
                message.error(e?.message || 'Ошибка финализации');
              }
            }}
          >Finalize Postmortem</Button>
          <Button
            type="primary"
            danger
            onClick={async () => {
              const sev = typeof item?.severity === 'string' ? parseInt(item?.severity, 10) : (item?.severity as any);
              if (sev === 1 || sev === 2) { setTkAction('close'); setTkOpen(true); return; }
              await closeIncident();
            }}
          >
            Close
          </Button>
          <Button
            type="primary"
            onClick={async () => {
              const sev = typeof item?.severity === 'string' ? parseInt(item?.severity, 10) : (item?.severity as any);
              if (sev === 1 || sev === 2) { setTkAction('close_with_postmortem'); setTkOpen(true); return; }
              await closeWithPostmortem();
            }}
          >
            Close with Postmortem
          </Button>
        </Space>
      </Space>

      <Card loading={loading} title="Карточка">
        <Descriptions column={1} size="small" bordered>
          <Descriptions.Item label="Title">{item?.title || '-'}</Descriptions.Item>
          <Descriptions.Item label="Status">{statusTag(item?.status)}</Descriptions.Item>
          <Descriptions.Item label="Severity">{severityTag(item?.severity)}</Descriptions.Item>
          <Descriptions.Item label="Source">{item?.source || '-'}</Descriptions.Item>
          <Descriptions.Item label="Trace">{item?.trace_id || '-'}</Descriptions.Item>
          <Descriptions.Item label="Detected">{item?.detected_at ? dayjs(item.detected_at).format('YYYY-MM-DD HH:mm:ss') : '-'}</Descriptions.Item>
          <Descriptions.Item label="Resolved">{item?.resolved_at ? dayjs(item.resolved_at).format('YYYY-MM-DD HH:mm:ss') : '-'}</Descriptions.Item>
          <Descriptions.Item label="Closed">{item?.closed_at ? dayjs(item.closed_at).format('YYYY-MM-DD HH:mm:ss') : '-'}</Descriptions.Item>
          <Descriptions.Item label="SLA">{item?.sla ? JSON.stringify(item.sla) : '-'}</Descriptions.Item>
        </Descriptions>
      </Card>

      <Card title="Действия">
        <Space wrap>
          <Button onClick={() => setAssignOpen(true)}>Assign</Button>
          <Button onClick={() => setEventOpen(true)}>Add Event</Button>
          <Button onClick={() => setLinkOpen(true)}>Add Link</Button>
        </Space>
      </Card>

      <Card title="Таймлайн">
        <Timeline>
          {events.map(ev => (
            <Timeline.Item key={String(ev.id)} color="blue">
              <div style={{ fontWeight: 600 }}>{ev.type || 'event'}</div>
              <div style={{ fontSize: 12, opacity: 0.8 }}>{ev.created_at ? dayjs(ev.created_at).format('YYYY-MM-DD HH:mm:ss') : ''} • {ev.actor || ''}</div>
              {ev.message ? <div style={{ marginTop: 4 }}>{ev.message}</div> : null}
              {ev.payload ? <pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(ev.payload, null, 2)}</pre> : null}
            </Timeline.Item>
          ))}
        </Timeline>
      </Card>

      <Card title="Связи">
        <Space direction="vertical" style={{ width: '100%' }}>
          {links.length === 0 ? <Typography.Text type="secondary">Нет связей</Typography.Text> : null}
          {links.map(l => (
            <div key={String(l.id)}>
              <Tag color="blue">{l.to_kind}</Tag> <Typography.Text code>{String(l.to_id)}</Typography.Text> {l.relation ? <Tag>{l.relation}</Tag> : null}
            </div>
          ))}
        </Space>
      </Card>

      <Card title="Postmortem">
        <Space wrap>
          <Button onClick={() => { window.open(`${API_BASE}/api/admin/incidents/${id}/postmortem/export?format=md&_cache_bust=${Date.now()}`, '_blank'); }}>Export MD</Button>
          <Button onClick={() => { window.open(`${API_BASE}/api/admin/incidents/${id}/postmortem/export?format=pdf&_cache_bust=${Date.now()}`, '_blank'); }}>Export PDF</Button>
          <Button
            disabled={!pmStatus?.has_draft && !pmStatus?.has_final}
            onClick={async () => {
              try {
                // Загрузим обе версии (если есть)
                if (pmStatus?.has_draft) {
                  const resp = await fetch(`${API_BASE}/api/admin/incidents/${id}/postmortem/export?format=md&status=draft&_cb=${Date.now()}`);
                  setPmDraftMD(await resp.text());
                } else {
                  setPmDraftMD('');
                }
                if (pmStatus?.has_final) {
                  const resp2 = await fetch(`${API_BASE}/api/admin/incidents/${id}/postmortem/export?format=md&status=final&_cb=${Date.now()}`);
                  setPmFinalMD(await resp2.text());
                } else {
                  setPmFinalMD('');
                }
                setPmCompareOpen(true);
              } catch (e: any) {
                message.error(e?.message || 'Ошибка загрузки версий');
              }
            }}
          >Compare draft vs final</Button>
        </Space>
        <div style={{ marginTop: 12 }}>
          <Descriptions size="small" column={1} bordered>
            <Descriptions.Item label="Final">
              {pmStatus?.has_final ? <Tag color="green">final</Tag> : <Tag>none</Tag>}
            </Descriptions.Item>
            <Descriptions.Item label="Draft">
              {pmStatus?.has_draft ? <Tag color="blue">draft</Tag> : <Tag>none</Tag>}
            </Descriptions.Item>
          </Descriptions>
        </div>
      </Card>

      <Modal open={assignOpen} onCancel={() => setAssignOpen(false)} onOk={() => { assignForm.submit(); }} title="Назначить исполнителя">
        <Form form={assignForm} layout="vertical" onFinish={async (v) => {
          try {
            await apiRequest(`/api/admin/incidents/${id}/events`, 'POST', { type: 'assign', ...v });
            setAssignOpen(false);
            assignForm.resetFields();
            await load();
            message.success('Назначено');
          } catch (e: any) {
            if (e?.status === 403) { message.error('Недостаточно прав (403)'); return; }
            message.error(e?.message || 'Ошибка назначения');
          }
        }}>
          <Form.Item name="assignee_tg_id" label="Telegram ID" rules={[{ required: true, message: 'Укажите tg_id' }]}>
            <Input placeholder="468326902" />
          </Form.Item>
          <Form.Item name="comment" label="Комментарий">
            <Input.TextArea rows={3} />
          </Form.Item>
        </Form>
      </Modal>

      <Modal open={eventOpen} onCancel={() => setEventOpen(false)} onOk={addEvent} title="Добавить событие">
        <Form form={eventForm} layout="vertical">
          <Form.Item name="type" label="Тип" rules={[{ required: true, message: 'Укажите тип' }]}>
            <Select options={[
              { value: 'comment', label: 'comment' },
              { value: 'update', label: 'update' },
              { value: 'rca_edit', label: 'rca_edit' },
            ]} />
          </Form.Item>
          <Form.Item name="message" label="Сообщение">
            <Input.TextArea rows={4} />
          </Form.Item>
          <Form.Item name="payload" label="Payload (JSON)">
            <Input.TextArea rows={4} placeholder='{"key":"value"}' />
          </Form.Item>
        </Form>
      </Modal>

      <Modal open={linkOpen} onCancel={() => setLinkOpen(false)} onOk={addLink} title="Добавить связь">
        <Form form={linkForm} layout="vertical">
          <Form.Item name="to_kind" label="К чему" rules={[{ required: true }]}>
            <Select options={[
              { value: 'incident', label: 'incident' },
              { value: 'runbook', label: 'runbook' },
              { value: 'kb', label: 'kb' },
              { value: 'trace', label: 'trace' },
            ]} />
          </Form.Item>
          <Form.Item name="to_id" label="ID" rules={[{ required: true }]}>
            <Input />
          </Form.Item>
          <Form.Item name="relation" label="Связь">
            <Input placeholder="relates_to | caused_by | fixes" />
          </Form.Item>
        </Form>
      </Modal>

      <TwoKeysModal
        open={tkOpen}
        onClose={() => setTkOpen(false)}
        onApproved={async (rid: string) => {
          try {
            if (tkAction === 'postmortem_finalize') {
              await apiRequest(`/api/admin/incidents/${id}/postmortem/finalize`, 'POST', { two_keys_request_id: rid });
              message.success('Postmortem финализирован');
              const s = await apiRequest(`/api/admin/incidents/${id}/postmortem/status`, 'GET');
              setPmStatus(s || null);
            } else if (tkAction === 'close_with_postmortem') {
              await closeWithPostmortem();
            } else if (tkAction === 'rca_edit_event' && pendingEvent) {
              await apiRequest(`/api/admin/incidents/${id}/events`, 'POST', pendingEvent);
              setPendingEvent(null);
              setEventOpen(false);
              eventForm.resetFields();
              await load();
              message.success('RCA обновлена');
            } else {
              await closeIncident();
            }
          } catch {}
        }}
      />

      <Modal
        open={pmCompareOpen}
        onCancel={() => setPmCompareOpen(false)}
        title="Postmortem: Draft vs Final"
        footer={<Button onClick={() => setPmCompareOpen(false)}>Close</Button>}
        width={1000}
      >
        <div style={{ display: 'flex', gap: 12 }}>
          <div style={{ flex: 1 }}>
            <Typography.Title level={5}>Draft</Typography.Title>
            <pre style={{ whiteSpace: 'pre-wrap', padding: 8, background: '#fafafa', border: '1px solid #eee', borderRadius: 4, maxHeight: 480, overflow: 'auto' }}>{pmDraftMD || '—'}</pre>
          </div>
          <div style={{ flex: 1 }}>
            <Typography.Title level={5}>Final</Typography.Title>
            <pre style={{ whiteSpace: 'pre-wrap', padding: 8, background: '#fafafa', border: '1px solid #eee', borderRadius: 4, maxHeight: 480, overflow: 'auto' }}>{pmFinalMD || '—'}</pre>
          </div>
        </div>
      </Modal>
    </Space>
  );
};

export default IncidentDetails;


